    /** Daftar seri milik satu brand (UUID). */
    export function getBatch4SeriByBrandId(brandId: string): ProdukKomersialBatch4Seri[] {
    return PK_BATCH4_SERI_LIST.filter(s => s.brandId === brandId);
    }

    /** Lookup satu seri via brandId + seriSlug (routing). */
    export function getBatch4SeriBySlug(brandId: string, seriSlug: string): ProdukKomersialBatch4Seri | undefined {
    return PK_BATCH4_SERI_LIST.find(s => s.brandId === brandId && s.slug === seriSlug);
    }

    /** Lookup seri via UUID. */
    export function getBatch4SeriByUUID(uuid: string): ProdukKomersialBatch4Seri | undefined {
    return PK_BATCH4_SERI_LIST.find(s => s.uuid === uuid);
    }
    